edits.newText:
When('the app is reloaded', function () {
  // Save localStorage state before reload
  const savedData = {};
  for (var i = 0; i < this.window.localStorage.length; i++) {
    var key = this.window.localStorage.key(i);
    savedData[key] = this.window.localStorage.getItem(key);
  }
  // Reload the app (creates new window)
  this.loadApp();
  // Restore localStorage data into the new window
  var ls = this.window.localStorage;
  for (var k in savedData) {
    if (savedData.hasOwnProperty(k)) {
      ls.setItem(k, savedData[k]);
    }
  }
  // Re-run init so the app reads the restored localStorage
  // loadApp already called window.eval(appSource) which runs self-executing init
  // The init reads from localStorage which should now be restored
  // But init already ran before state was restored. Re-run init manually.
  this.window.todoApp.init();
});

